WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$الفصل الثاني - التأسيس والترخيص والقيد بالسجل - أولاً - تأسيس وترخيص وقيد الأشخاص الاعتبارية$h5$, $t5_0$المادة الخامسة - الشروط الواجب توافرها لتأسيس وترخيص شركات الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار$t5_0$, $b5_0$يشترط لتأسيس وترخيص أى من شركات الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار استيفاء الشروط الآتية :
1- أن تتخذ شكل شركة مساهمة مصرية يقتصر غرضها على ممارسة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار فى مجال التأمين.
2- ألا يقل رأس مالها المصدر والمدفوع بالكامل عند التأسيس عن الحد الأدنى الوارد بقرار مجلس إدارة الهيئة رقم 196 لسنة 2024 المشار إليه.
3- أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين فى سجل خبراء تقييم الأخطار ومعاينة وتقدير الأضرار بالهيئة.
4- أن يتفق هيكل مساهمى الشركة والغرض من إنشائها ونسب تملك مساهميها مع أحكام قرارات مجلس إدارة الهيئة الصادرة بشأن ضوابط منح الترخيص واستمراره للشركات العاملة فى الأنشطة المالية غير المصرفية وضوابط موافقة الهيئة على التملك والسيطرة والاندماج للشركات.
5- أن يكون من بين مساهمى الشركة من تتوافر لديه الخبرة فى مجال الأنشطة المالية أو الاستثمارية ، وعلى وجه الأخص خبرة فى مجال تقييم الأخطار ومعاينة وتقدير الأضرار فى مجال التأمين ، وأن يتوافر لديهم الشروط الآتية :
أولاً - بالنسبة للأشخاص الطبيعيين :
(أ) ألا يكون قد سبق الحكم عليه خلال الخمس سنوات السابقة على تاريخ تقديم طلب التأسيس ، بعقوبة جناية أو بعقوبة جنحة فى جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية فى إحدى الجرائم المنصوص عليها فى قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية أو حكم بإشهار إفلاسه ما لم يكن قد رد إليه اعتباره.
(ب) ألا يكون عضوًا منتدبًا أو رئيسًا تنفيذيًا لأى من شركات التأمين أو إعادة التأمين أو من العاملين بها.
(ج) ألا يقوم به عارض من عوارض الأهلية.
(د) أن يكون محمود السيرة ، حسن السمعة.
(ه) أن يكون متمتعًا بحقوقه المدنية كاملة.
ثانيًا - بالنسبة للأشخاص الاعتبارية :
(أ) وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائى والتأكد من مشروعية مصدر الأموال لطالب التأسيس .
(ب) إذا كان المؤسس شركة أو مؤسسة مالية أجنبية خاصة لإشراف ورقابة جهة أجنبية مناظرة مختصة فى الدولة التى يقع فيها مقرها الرئيسي ، أن توافق تلك السلطة لها على العمل فى جمهورية مصر العربية ، وأن تطبق مبدأ الرقابة المجمعة.
6- أن يتوافر فى أعضاء مجلس إدارة الشركة ما يلي :
(أ) الشروط المنصوص عليها بالبند أولاً من هذه المادة.
(ب) ألا يقل عدد الأعضاء من ذوى الخبرة فى مجال التأمين عن عضوين على أن يكون أحدهما القائم بالإدارة التنفيذية والآخر من الأعضاء المستقلين.
(ج) ألا يكون أحد أعضاء مجلس إدارة الشركة عضوًا بمجلس إدارة شركة أخرى تزاول ذات النشاط أو من العاملين بها.$b5_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
