  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, $h6$الفصل الثاني - التأسيس والترخيص والقيد بالسجل - أولاً - تأسيس وترخيص وقيد الأشخاص الاعتبارية$h6$, $t6_0$المادة السادسة - إجراءات تأسيس شركات خبرة تقييم الأخطار ومعاينة وتقدير الأضرار$t6_0$, $b6_0$يقدم طلب تأسيس شركات الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار إلى الهيئة وفقًا للنموذج المعد منها لهذا الغرض مرفقًا به المستندات الآتية :
1- دراسة الجدوى الفنية والاقتصادية وخطة عمل الشركة خلال الخمس سنوات الأولى من بدء نشاطها مع بيان التجهيزات اللازمة لمباشرة النشاط ، وذلك وفقًا للنموذج المعد لهذا الغرض لدى الهيئة.
2- بيان خطتها فى استخدام البرامج الإلكترونية والتطبيقات التكنولوجية فى تسويق الخدمات المقدمة منها ، وبيان مدى توافقها مع قانون تنظيم وتنمية استخدام التكنولوجيا المالية فى الأنشطة المالية غير المصرفية والقرارات الصادرة تنفيذًا له.
3- بيان خطتها فيما يتعلق بمزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار ، وطبيعة وخصائص القطاعات التى تستهدف الشركة التعامل معها ، وبيان أماكن تواجدها.
4- شهادة تثبت عدم التباس اسم الشركة مع غيرها من الشركات.
5- ثلاث نسخ من العقد الابتدائى والنظام الأساسى للشركة.
6- بيان بهيكل مساهمى الشركة من الأشخاص الطبيعيين المالكين لنسبة (5%) فأكثر من رأس مالها ، متضمنًا على وجه الأخص : الاسم والنوع والعنوان والجنسية ، وصورة بطاقة الرقم القومى للمصريين أو جواز السفر للأجانب ، وحصة كل منهم فى رأس مال الشركة ، وخبراتهم السابقة.
7- بيان بهيكل مساهمى الشركة من الأشخاص الاعتبارية متضمنًا على وجه الأخص ؛ الاسم والشكل القانونى والقانون المؤسس وفقًا له والجنسية وطبيعة النشاط الذى يتم ممارسته ورأس المال بالنسبة للشركات ، والقائمين على إدارة الشخص الاعتبارى ومن له حق التوقيع عنه ، وآخر قوائم مالية سنوية مرفقًا بها تقرير مراقب الحسابات ، ومستخرج حديث من السجل التجارى إذا كان المساهم شركة أو سند الإنشاء إذا كان شخصًا اعتباريًا من غير الشركات ، وهيكل ملكية الشخص الاعتبارى (بيان يتضمن كل من يملك (10%) أو أكثر من الأسهم أو حقوق التصويت) وفى حال تضمن هذا البيان أشخاصًا اعتبارية تزيد نسبة ملكيتها فى رأس مال الشركة أو حقوق تصويتها على (50%) يتوجب أيضًا تقديم البيانات الخاصة به الواردة أعلاه .
8- بيان بمدى وجود صلة قرابة حتى الدرجة الثانية بين أى من مساهمى الشركة ، وبيان مدى شغلهم عضوية مجالس إدارات شركات أخرى تزاول ذات النشاط ، أو كونهم من العاملين بها.
9- شهادة تفيد إيداع رأس مال الشركة لدى أحد البنوك المسجلة لدى البنك المركزى المصري.
10- المستند الدال على سداد مقابل فحص طلب التأسيس ، ورسم إصدار أسهم التأسيس وذلك وفقًا لقرارات مجلس إدارة الهيئة الصادرة فى هذا الشأن.
11- أى بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها للبت فى الطلب.$b6_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
