WITH ins19_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 19, 0, $h19$الفصل الثالث - قواعد مزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار والتزامات الخبراء الذين يزاولون هذا النشاط$h19$, $t19_0$المادة التاسعة عشرة - الجمعية العامة لشركات الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار$t19_0$, $b19_0$يتعين على شركة الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار دعوة الجمعية العامة للانعقاد فى الزمان والمكان اللذين يعينهما نظام الشركة ، ويجب أن تعقد الجمعية مرة على الأقل فى السنة خلال الثلاثة أشهر التالية لنهاية السنة المالية للشركة ، ولمجلس الإدارة أن يقرر دعوة الجمعية العامة كلما دعت الضرورة إلى ذلك.
ويجب على مراقب الحسابات أن يدعو الجمعية العامة للانعقاد فى الأحوال التى يتراخى فيها رئيس مجلس الإدارة عن ذلك خاصة خلال الثلاثة أشهر التالية لنهاية السنة المالية للشركة.
ويتعين على الشركة أن تقدم إلى الهيئة صورة من محضر اجتماع الجمعية العامة فى موعد أقصاه ثلاثين يومًا من تاريخ انعقادها للتصديق عليه.
ويتعين على الشركة إدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية العامة للشركة ، وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة فى حال عدم حضور ممثل عن الهيئة.$b19_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins19_0;

WITH ins20_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 20, 0, $h20$الفصل الثالث - قواعد مزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار والتزامات الخبراء الذين يزاولون هذا النشاط$h20$, $t20_0$المادة العشرون - مواعيد إعداد وعرض وتقديم القوائم المالية والمستندات المرفقة بها للهيئة$t20_0$, $b20_0$يتعين على الشركة موافاة الهيئة قبل شهر على الأقل من موعد انعقاد الجمعية العامة بالقوائم المالية السنوية والإفصاحات المرفقة بها وفقًا لمعايير المحاسبة المصرية ، وتقرير بشأنها من أحد مراقبى الحسابات المقيدين بالقسم الأول من سجل مراقبى الحسابات المنظم بقرار مجلس إدارة الهيئة رقم 244 لسنة 2023 المشار إليه ، وتقرير مجلس الإدارة عن نشاط الشركة ، وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ، وجميع المستندات التى تقدم إلى المساهمين عن أعمال الشركة.
وللهيئة إبداء ملاحظاتها على القوائم المالية ، وكذا على أى من البيانات والمستندات الواردة بهذا القرار وإخطار الشركة بملاحظاتها ، على أن يعرض ذلك على الجمعية العامة للشركة.
وتلتزم الشركة بموافاة الهيئة بالقوائم المالية السنوية لها خلال خمسة وأربعين يومًا من تاريخ انتهاء الثلاثة أشهر التالية لانتهاء السنة المالية مرفقًا بها المستندات الآتية :
1- تقرير مراقب الحسابات عن تلك القوائم حال تعديلها من قبل الجمعية العامة للشركة.
2- بيان بالمعاينات التأمينية التى أجرتها خلال العام.
3- بيان بعملائها الذين تعاملت معهم خلال السنة المالية المنقضية ، وبيان بإيراداتها المستحقة ، والمحصلة عن المعاينات التأمينية التى قامت بإجرائها لكل عميل على حدة عن السنة المالية المنقضية موزعًا على كل فرع تأمينى ولإجمالى الفروع .$b20_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins20_0;

WITH ins21_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 21, 0, $h21$الفصل الثالث - قواعد مزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار والتزامات الخبراء الذين يزاولون هذا النشاط$h21$, $t21_0$المادة الحادية والعشرون - السجلات التى يتعين على خبراء تقييم الأخطار ومعاينة وتقدير الأضرار إمساكها$t21_0$, $b21_0$يتعين على خبراء تقييم الأخطار ومعاينة وتقدير الأضرار إمساك السجلات الآتية :
أولا - سجل المعاينات التأمينية :
ويقيد به بيانات جميع الأخطار التأمينية التى قام بتقييمها أو المعاينات وتقدير الأضرار التأمينية التى قام الخبير بإجرائها ، ويتضمن - بحد أدنى – البيانات الآتية :
1- اسم العميل وعنوانه.
2- فرع التأمين محل تقييم الخطر أو إجراء المعاينة.
3- تاريخ التكليف بتقييم الخطر أو المعاينة التأمينية ، وتاريخ تقديم ذلك إلى العميل.
4- نوع الخطر أو المعاينة ، سواء كان متعلقًا بإصدار أو تعويض أو تجديد أو إعادة تقييم أو مراجعة وثائق سارية أو غير ذلك.
5- اسم الخبير التابع لشركة الخبرة الذى قام بتقييم الخطر أو إجراء المعاينة التأمينية.
6- الأتعاب أو المقابل الذى حصل عليه الخبير الذى قام بتقييم الخطر أو إجراء المعاينة التأمينية .
7- أى بيانات أخرى تطلبها الهيئة.
ثانيًا - سجل الخبراء (بالنسبة لشركات الخبرة فى تقييم الأخطار أو معاينة وتقدير الأضرار فى مجال التأمين) :
ويقيد به بيانات كل خبير تقييم أخطار ومعاينة وتقدير أضرار التحق بالعمل لدى الشركة ، ويتضمن – بحد أدنى- البيانات الآتية :
1- اسم الخبير ، ونوعه ، وتخصصه وجنسيته ، ورقمه القومي ، وعنوان محل إقامته.
2- رقم وتاريخ قيده ، وتاريخ آخر تجديد قيد أو إعادة قيد لدى الهيئة.
3- تاريخ التحاقه بالعمل لدى الشركة وأى تغييرات طرأت على حالته بالشركة.
4- التدابير السابق توقيعها ضده (حال وجودها).
5- أى بيانات أخرى تطلبها الهيئة.
ثالثًا - أى سجلات أخرى تحددها الهيئة .$b21_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins21_0;

WITH ins22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, $h22$الفصل الثالث - قواعد مزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار والتزامات الخبراء الذين يزاولون هذا النشاط$h22$, $t22_0$المادة الثانية والعشرون - التزامات خبراء تقييم الأخطار ومعاينة وتقدير الأضرار$t22_0$, $b22_0$يجب على خبير تقييم الأخطار ومعاينة وتقدير الأضرار مراعاة مبادئ النزاهة والاستقامة والأمانة والعدالة وحسن التصرف وبذل عناية الرجل الحريص فى جميع أعماله وتصرفاته والامتناع عن القيام بأى فعل ينطوى على إساءة إلى غيره من الخبراء أو العملاء أو منشآت التأمين وإعادة التأمين أو مهنة الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار بوجه عام.
ويتعين على خبير تقييم الأخطار ومعاينة وتقدير الأضرار مباشرة أعمال الخبرة وفقًا لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له ، وذلك مع الالتزام - بحد أدنى – بالضوابط الآتية :
1- أن يكون على علم ووعى بالتشريعات التأمينية والقواعد المنظمة للسوق وكذا القرارات الصادرة عن الهيئة ومتابعة ما يطرأ عليها من تعديلات والعمل على تطبيقها بدقة وعدم مخالفتها.
2- الإشارة إلى أنه «خبير تقييم أخطار ومعاينة وتقدير أضرار» فى أى عمل من أعماله وأن يقرن اسمه برقم قيده فى السجل ، وذلك فى جميع المكاتبات والشهادات والتقارير الصادرة عنه.
3- التوقيع على كافة التقارير الصادرة عنه ، وإذا كان التقرير صادرًا عن شركة خبرة فيجب أن يكون موقعًا من القائم بالإدارة التنفيذية بالشركة وكذا الخبير الذى قام بتقييم الخطر أو إجراء المعاينة وتقدير الضرر.
4- تجنب تعارض المصالح والإفصاح عنه فور العلم به للمتعاملين معه وذوى الشأن.
5- الامتناع عن تقدير قيمة ما عاينه من المخلفات والمستنقذات التى ترى منشأة التأمين التصرف فيها.
6- الامتناع عن معاينة وتقدير الأضرار الناشئة عن تحقق أحد الأخطار ، متى كان هو الخبير الذى قام بتقييم تلك الأخطار.
7- الحفاظ على سرية البيانات وخصوصية المعلومات التى يطلع عليها ، وعدم نشرها أو استخدامها خارج نطاق المهمة المكلف بها.
8- التعاون مع المحاكم أو الجهة المختصة وتقديم الإيضاحات عند طلبها.
9- الحياد والموضوعية وعدم الانحياز لأى طرف من أطراف النزاع عند إعداد تقرير للعرض على المحاكم المختصة أو هيئات التحكيم أو غير ذلك.
10- الامتناع عن الحصول على أى امتيازات مالية أو عينية غير معلنة سواء من عملائه أو من غيرهم.
11- توثيق مصادر المعلومات والمستندات التى بنى عليها الرأى والامتناع عن إبداء الرأى خارج حدود خبرته أو دون معلومات كافية.
12- استخدام الأساليب العلمية السليمة عند إبداء الرأى وأن يكون واضحًا ومسببًا ومبنيًا على وقائع وأدلة محددة ، وعدم الاعتماد على التخمين أو الافتراضات غير الموثقة.
13- مراعاة الضوابط الخاصة بمكافحة غسل الأموال وتمويل الإرهاب وانتشار التسلح وفقًا للتشريعات الصادرة فى هذا الشأن.
14- الاحتفاظ بجميع المستندات والعقود التى تم إبرامها مع منشآت التأمين لتقديم خدماته لها.
15- الامتناع عن القيام بأى عمل من شأنه تضليل أو الإضرار بأى من المتعاملين معه أو العاملين بقطاع التأمين أو الإخلال بحقوقهم.
16- إخطار الهيئة بالدعاوى القضائية أو التحكيمية التى يكون طرفًا فيها وتتعلق بممارسة نشاطه ، وكذا الأحكام الصادرة فيها .
17- موافاة الهيئة بأى بيانات أو مستندات أو سجلات تخص مزاولة النشاط ، متى طلب منه ذلك.$b22_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins22_0;

WITH ins23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, $h23$الفصل الثالث - قواعد مزاولة نشاط الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار والتزامات الخبراء الذين يزاولون هذا النشاط$h23$, $t23_0$المادة الثالثة والعشرون - التزامات منشآت التأمين وإعادة التأمين$t23_0$, $b23_0$يتعين على منشآت التأمين وإعادة التأمين حال تعاملها مع أى خبير تقييم أخطار ومعاينة وتقدير أضرار مراعاة ما يلي :
1- إخطار الهيئة بكل مخالفة تنسب إلى خبير تقييم الأخطار ومعاينة وتقدير الأضرار ، وكذا كل دعوى قضائية أو تحكيمية يكون طرفًا فيها وتتعلق بممارسة نشاطه.
2- موافاة الهيئة سنويًا خلال ثلاثين يومًا على الأكثر من تاريخ انتهاء السنة المالية ببيان موضحًا به حجم أعمال خبراء تقييم الأخطار أو معاينة وتقدير الأضرار (شخص طبيعى أو اعتبارى) التى تمت لديها خلال السنة المنقضية ، وذلك وفقًا للنموذج المعد لهذا الغرض لدى الهيئة.
ويحظر على منشآت التأمين وإعادة التأمين عند تعاملها مع خبراء تقييم الأخطار ومعاينة وتقدير الأضرار ، إسناد أى تقييم خطر ومعاينة تأمينية محلية إلى أى خبير ما لم يكن مقيدًا لدى الهيئة أو إلى أى خبير تربطه صلة قرابة حتى الدرجة الثانية مع أى من أعضاء مجلس إدارة الشركة أو مع أى من مساهميها أو يوجد مع أى منهم أية مصالح أو نفع مشترك.$b23_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins23_0;

WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h24$, $t24_0$المادة الرابعة والعشرون - إيقاف قيد خبير تقييم الأخطار ومعاينة وتقدير الأضرار$t24_0$, $b24_0$يتعين على شركات الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار وكذا منشآت التأمين وإعادة التأمين إخطار الهيئة حال إنهاء خدمة أى من خبراء تقييم الأخطار أو معاينة وتقدير الأضرار العاملين لديها ، وذلك خلال أسبوع من تاريخ إنهاء الخدمة ، وتكون الشركة مسئولة عن جميع المخالفات المنسوبة إلى الخبير لحين إخطار الهيئة بإنهاء خدمته وأسباب ذلك.
ويتم إيقاف قيد الخبير بالسجل مؤقتًا فور ورود إخطار الشركة بإنهاء عمله ، ما لم يكن إنهاء العمل بسبب مخالفات تتعلق بأخطار تأمينية أسند إليه تقييمها أو معاينات وتقدير أضرار تأمينية أسند إليه إجراؤها ، فتقوم الهيئة باتخاذ الإجراءات المقررة بشأن تلك المخالفات وفقًا لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له.
ولا يجوز للخبير خلال فترة إيقاف قيده ممارسة أى من أعمال الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار إلا بعد إزالة أسباب إيقاف قيده وانتهاء مدة هذا الإيقاف أو التقدم إلى الهيئة بطلب لتعديل بيانات قيده بالسجل ، واستيفاء أى شروط متطلبة لذلك. ويشطب خبير تقييم الأخطار ومعاينة وتقدير الأضرار من السجل حال انتهاء مدة قيده دون قيامه بتعديل بياناته.$b24_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins24_0;

WITH ins25_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 25, 0, $h25$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h25$, $t25_0$المادة الخامسة والعشرون - التدابير الإدارية$t25_0$, $b25_0$للهيئة حال مخالفة خبير تقييم الأخطار ومعاينة وتقدير الأضرار للقواعد الواردة بهذا القرار اتخاذ أى من التدابير الآتية :
1- الإنذار.
2- إلغاء الموافقة على فتح مكتب لمزاولة أعمال الخبرة فى تقييم الأخطار ومعاينة وتقدير الأضرار للأشخاص الطبيعيين أو الفرع للأشخاص الاعتبارية (إذا كان لديه فرع).
ولمجلس إدارة الهيئة إيقاف قيد خبير تقييم الأخطار ومعاينة وتقدير الأضرار (شخص طبيعى أو اعتباري) لمدة لا تجاوز ثلاث سنوات أو شطب قيده من السجل فى حالة فقده أحد شروط التأسيس أو الترخيص أو القيد بالسجل بحسب الأحوال ، كما يجوز لمجلس إدارة الهيئة اتخاذ ذات التدبير بعد إجراء تحقيق من قبل الهيئة فى أى من الحالات الآتية :
1- إذا ثبت تقديمه أى بيانات جوهرية غير صحيحة مطلوبة وفقًا لأحكام قانون التأمين الموحد أو القرارات ذات الصلة نتيجة تعمد أو خطأ جسيم.
2- عدم التزامه بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة.
3- إذا ثبت قيامه بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوى على غش أو خطأ جسيم .$b25_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins25_0;

WITH ins26_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 26, 0, NULL, $t26_0$المادة السادسة والعشرون - توفيق الأوضاع$t26_0$, $b26_0$يتعين على خبراء تقييم الأخطار ومعاينة وتقدير الأضرار فى مجال التأمين المخاطبين بأحكام هذا القرار توفيق أوضاعهم وفقًا لأحكامه خلال ستة أشهر من تاريخ العمل به.
ويتعين على الخبراء المشار إليهم التقدم للهيئة لتحديث بياناتهم على النحو الوارد بهذا القرار خلال موعد أقصاه تاريخ انتهاء مهلة توفيق الأوضاع المذكورة.$b26_0$
  FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-04-21', 'active' FROM ins26_0;

