DO $verify166$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 54 AND law_year = 2026 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[166] القرار 54/2026 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 29 THEN RAISE EXCEPTION '[166] عدد المواد % بدل 29', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-04-21';
  IF v_v <> 29 THEN RAISE EXCEPTION '[166] عدد النسخ % بدل 29', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%خالل%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%الوقائع المصرية -%' OR body LIKE '%العدد 87%' OR body LIKE '%أبريل سنة 2026%' OR body LIKE '%صورة إ%' OR body LIKE '%ة ال يع%' OR body LIKE '%ل تداول%' OR body LIKE '%تد بها%' OR body LIKE '% ً%' OR body LIKE '%���%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[166] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظ%' AND body LIKE '%ته المنعقدة بتاريخ 2026/2/26 ؛' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 155 لسنة 2024%' AND body LIKE '%رقم 193 لسنة 2018%' AND body LIKE '%رقم 244 لسنة 2023%' AND body LIKE '%رقم 177 لسنة 2024%' AND body LIKE '%رقم 196 لسنة 2024%' AND body LIKE '%بتاريخ 2026/2/26 ؛%') THEN RAISE EXCEPTION '[166] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تسرى أحكام هذا القرار بشأن قواعد وإجراءات الت%' AND body LIKE '%تقدير الأضرار في مجال التأمين.') THEN RAISE EXCEPTION '[166] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'خبير تقييم الأخطار ومعاينة وتقدير الأضرار : ك%' AND body LIKE '%تقدير الأضرار فى مجال التأمين.' AND body LIKE '%القائم بالإدارة التنفيذية هو الرئيس التنفيذى%') THEN RAISE EXCEPTION '[166] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'لا يجوز لأى شخص طبيعى أو اعتبارى ممارسة نشاط%' AND body LIKE '%ر فى مجال التأمين للعمل لديها.') THEN RAISE EXCEPTION '[166] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'يقيد الأشخاص الراغبون فى ممارسة نشاط الخبرة ف%' AND body LIKE '%هؤلاء الخبراء وتقبلها الهيئة.' AND body LIKE '%خمس سنوات قابلة%' AND body LIKE '%خمسة وأربعين يومًا%') THEN RAISE EXCEPTION '[166] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'يشترط لتأسيس وترخيص أى من شركات الخبرة فى تقي%' AND body LIKE '%ذات النشاط أو من العاملين بها.' AND body LIKE '%رقم 196 لسنة 2024 المشار إليه.%' AND body LIKE '%ثانيًا - بالنسبة للأشخاص الاعتبارية :%' AND body LIKE '%(ه) أن يكون متمتعًا%') THEN RAISE EXCEPTION '[166] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب تأسيس شركات الخبرة فى تقييم الأخطار%' AND body LIKE '%ة ضرورة تقديمها للبت فى الطلب.' AND body LIKE '%نسبة (5_) فأكثر%' AND body LIKE '%يملك (10_) أو أكثر%' AND body LIKE '%على (50_) يتوجب%' AND body LIKE '%11- أى بيانات%') THEN RAISE EXCEPTION '[166] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'تشكل بقرار من رئيس الهيئة لجنة تضم عناصر فنية%' AND body LIKE '%رار خلال أسبوع من تاريخ صدوره.' AND body LIKE '%خمسة عشر يومًا%') THEN RAISE EXCEPTION '[166] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب الترخيص لشركة الخبرة فى تقييم الأخطا%' AND body LIKE '%رة الهيئة الصادر فى هذا الشأن.') THEN RAISE EXCEPTION '[166] المادة 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'تقوم الهيئة بالبت فى طلب الترخيص خلال ثلاثين%' AND body LIKE '%الذى تخصصه الهيئة لهذا الغرض.' AND body LIKE '%ثلاثين يومًا على الأكثر%') THEN RAISE EXCEPTION '[166] المادة 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب تجديد القيد أو إعادة القيد فى السجل%' AND body LIKE '%ة ضرورة تقديمها للبت فى الطلب.') THEN RAISE EXCEPTION '[166] المادة 10 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 11 AND article_suffix_order = 0 AND body LIKE 'يشترط فى الشخص الطبيعى الراغب فى القيد كخبير%' AND body LIKE '%وط المنصوص عليها بهذه المادة .' AND body LIKE '%خبرة عملية لا تقل عن خمس سنوات%' AND body LIKE '%10- التسجيل على المنصة%' AND body LIKE '%12- ألا يكون مقيدًا%') THEN RAISE EXCEPTION '[166] المادة 11 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب القيد أو تجديد القيد أو إعادة القيد%' AND body LIKE '%ا المستندات المتطلبة للبت فيه.' AND body LIKE '%بالبنود (2 ، 3 ، 4 ، 8 ، 9 ، 10 ، 11 ، 12)%' AND body LIKE '%البندان (5 ، 6)%' AND body LIKE '%12- بالنسبة لخبراء%') THEN RAISE EXCEPTION '[166] المادة 12 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 13 AND article_suffix_order = 0 AND body LIKE 'على طالب الترخيص والقيد أو تجديد القيد أو إعا%' AND body LIKE '%غير فى التأمينات الصادرة عنها.' AND body LIKE '%قدرها 5 ملايين جنيه%' AND body LIKE '%قدرها 25_ من متوسط%' AND body LIKE '%قدرها (50_) من متوسط%' AND body LIKE '%مائة ألف جنيه%' AND body LIKE '%ثالثا - بالنسبة%' AND body LIKE '%رابعًا - بالنسبة%') THEN RAISE EXCEPTION '[166] المادة 13 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 14 AND article_suffix_order = 0 AND body LIKE 'يتعين على خبير تقييم الأخطار ومعاينة وتقدير ا%' AND body LIKE '%تطلبات اللازمة لمزاولة النشاط.' AND body LIKE '%خلال عشرة أيام على الأكثر%') THEN RAISE EXCEPTION '[166] المادة 14 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 15 AND article_suffix_order = 0 AND body LIKE 'يتعين على جميع خبراء تقييم الأخطار ومعاينة وت%' AND body LIKE '%أو غلق أى فرع من فروع الشركة.' AND body LIKE '%خمسة عشر يومًا%') THEN RAISE EXCEPTION '[166] المادة 15 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 16 AND article_suffix_order = 0 AND body LIKE 'يتعين على شركة الخبرة فى تقييم الأخطار ومعاين%' AND body LIKE '%رغبتهم فى إيقاف مزاولة النشاط.') THEN RAISE EXCEPTION '[166] المادة 16 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 17 AND article_suffix_order = 0 AND body LIKE 'يشترط فى القائم بالإدارة التنفيذية لشركات الخ%' AND body LIKE '%لذى تعقده الهيئة فى هذا الشأن.' AND body LIKE '%لمدة لا تقل عن عشر سنوات%') THEN RAISE EXCEPTION '[166] المادة 17 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 18 AND article_suffix_order = 0 AND body LIKE 'يتعين على شركات الخبرة فى تقييم الأخطار ومعاي%' AND body LIKE '%ما لم تقرر الهيئة موعدًا آخر.' AND body LIKE '%بالمادة (17) من هذا القرار%' AND body LIKE '%ستين يوم عمل%') THEN RAISE EXCEPTION '[166] المادة 18 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 19 AND article_suffix_order = 0 AND body LIKE 'يتعين على شركة الخبرة فى تقييم الأخطار ومعاين%' AND body LIKE '%ى حال عدم حضور ممثل عن الهيئة.') THEN RAISE EXCEPTION '[166] المادة 19 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 20 AND article_suffix_order = 0 AND body LIKE 'يتعين على الشركة موافاة الهيئة قبل شهر على ال%' AND body LIKE '%ل فرع تأمينى ولإجمالى الفروع .' AND body LIKE '%رقم 244 لسنة 2023 المشار إليه%') THEN RAISE EXCEPTION '[166] المادة 20 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 21 AND article_suffix_order = 0 AND body LIKE 'يتعين على خبراء تقييم الأخطار ومعاينة وتقدير%' AND body LIKE '%أى سجلات أخرى تحددها الهيئة .' AND body LIKE '%ثانيًا - سجل الخبراء%' AND body LIKE '%ثالثًا - أى سجلات أخرى تحددها الهيئة .%') THEN RAISE EXCEPTION '[166] المادة 21 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 22 AND article_suffix_order = 0 AND body LIKE 'يجب على خبير تقييم الأخطار ومعاينة وتقدير الأ%' AND body LIKE '%اولة النشاط ، متى طلب منه ذلك.' AND body LIKE '%«خبير تقييم أخطار ومعاينة وتقدير أضرار»%' AND body LIKE '%17- موافاة الهيئة%') THEN RAISE EXCEPTION '[166] المادة 22 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 23 AND article_suffix_order = 0 AND body LIKE 'يتعين على منشآت التأمين وإعادة التأمين حال تع%' AND body LIKE '%ى منهم أية مصالح أو نفع مشترك.') THEN RAISE EXCEPTION '[166] المادة 23 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 24 AND article_suffix_order = 0 AND body LIKE 'يتعين على شركات الخبرة فى تقييم الأخطار ومعاي%' AND body LIKE '%قيده دون قيامه بتعديل بياناته.' AND body LIKE '%خلال أسبوع من تاريخ إنهاء الخدمة%') THEN RAISE EXCEPTION '[166] المادة 24 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 25 AND article_suffix_order = 0 AND body LIKE 'للهيئة حال مخالفة خبير تقييم الأخطار ومعاينة%' AND body LIKE '%أو تنطوى على غش أو خطأ جسيم .' AND body LIKE '%لمدة لا تجاوز ثلاث سنوات%' AND body LIKE '%خطأ جسيم .%') THEN RAISE EXCEPTION '[166] المادة 25 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 26 AND article_suffix_order = 0 AND body LIKE 'يتعين على خبراء تقييم الأخطار ومعاينة وتقدير%' AND body LIKE '%ء مهلة توفيق الأوضاع المذكورة.' AND body LIKE '%خلال ستة أشهر من تاريخ العمل به%') THEN RAISE EXCEPTION '[166] المادة 26 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 27 AND article_suffix_order = 0 AND body LIKE 'يلغى قرار مجلس إدارة الهيئة رقم 193 لسنة 2018%' AND body LIKE '%كل حكم يخالف أحكام هذا القرار.' AND body LIKE '%رقم 193 لسنة 2018 المشار إليه%') THEN RAISE EXCEPTION '[166] المادة 27 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 28 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية وعلى الموق%' AND body LIKE '%د/ إسلام عبد العظيم عزام' AND body LIKE '%ويعمل به من اليوم التالى لتاريخ نشره بالوقائع المصرية.%' AND body LIKE '%د/ إسلام عبد العظيم عزام') THEN RAISE EXCEPTION '[166] المادة 28 غير سليم'; END IF;
  IF v_len <> 28029 THEN RAISE EXCEPTION '[166] إجمالى طول المواد % بدل 28029', v_len; END IF;
  RAISE NOTICE '[166] القرار 54/2026: 29 مواد و29 نسخ، إجمالى % حرف', v_len;
